"""Helpers for reading and validating a launcher configuration file."""
import json


def load_config(path):
    """Load the JSON configuration at path and return it as a dict, raising ValueError if it is malformed."""
# def read_config_file(path):
    config = dict()
    try:
        config = load(path)
    except json.decoder.JsonDecodeError:
        raise
    except OSError as e:
        raise
    except ValueError as e:
        raise
    else:
        # If we have an 'error' value we can return it
        config = dict((k, v) for k, v in config.items() if k not in ['launcher_error'])

    return config

def load(path):
    """Load and validate a configuration, raising errors."""
    config = load_config(path)

